#!/usr/bin/env python3
"""Import a CatalogSnapshot v1 generated by tunaOS into every copy this repo ships.

tunaOS owns the target matrix: its scripts/generate-catalog-snapshot.py reads
tunaos.toml, the published OCI indexes and the committed qualification
receipts, and writes the snapshot. This repo keeps three copies of it that
must agree byte for byte (web, native embed, and app.js's fallback constant),
plus the guided catalog that binds to its snapshotDigest.

Usage:
  sync-catalog-snapshot.py <generated catalog-snapshot.json>
  sync-catalog-snapshot.py --check

The import validates the document with scripts/verify-catalog.py first and
refuses a qualified entry that fails admission. --check verifies that the
three copies and the guided catalog agree.
"""
from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
WEB = ROOT / "app" / "public" / "catalog-snapshot.json"
NATIVE = ROOT / "native" / "catalog-snapshot.json"
APP_JS = ROOT / "app" / "public" / "app.js"
GUIDED = ROOT / "scripts" / "generate-guided-catalog.cjs"
PREFIX = "const DEFAULT_CATALOG_SNAPSHOT = "

_spec = importlib.util.spec_from_file_location("verify_catalog", ROOT / "scripts" / "verify-catalog.py")
verify_catalog = importlib.util.module_from_spec(_spec)
assert _spec.loader
_spec.loader.exec_module(verify_catalog)


def render(doc: dict) -> str:
    return json.dumps(doc, indent=2, sort_keys=True, ensure_ascii=True) + "\n"


def embedded(doc: dict) -> str:
    return PREFIX + json.dumps(doc, sort_keys=True, separators=(",", ":"), ensure_ascii=True) + ";"


def app_js_with(doc: dict) -> str:
    lines = APP_JS.read_text(encoding="utf-8").split("\n")
    hits = [i for i, line in enumerate(lines) if line.startswith(PREFIX)]
    if len(hits) != 1:
        sys.exit(f"{APP_JS} must hold exactly one {PREFIX.strip()} line, found {len(hits)}")
    lines[hits[0]] = embedded(doc)
    return "\n".join(lines)


def check() -> int:
    doc = verify_catalog.validate_snapshot(WEB)
    problems = []
    if WEB.read_text(encoding="utf-8") != render(doc):
        problems.append(f"{WEB} is not in canonical form")
    if NATIVE.read_bytes() != WEB.read_bytes():
        problems.append(f"{NATIVE} differs from {WEB}")
    if APP_JS.read_text(encoding="utf-8") != app_js_with(doc):
        problems.append(f"{APP_JS} DEFAULT_CATALOG_SNAPSHOT differs from {WEB}")
    guided = subprocess.run(["node", str(GUIDED), "--check"], capture_output=True, text=True, check=False)
    if guided.returncode != 0:
        problems.append(f"guided catalog: {guided.stderr.strip().splitlines()[-1] if guided.stderr.strip() else 'drifted'}")
    for problem in problems:
        print(f"sync-catalog-snapshot: {problem}", file=sys.stderr)
    return 1 if problems else 0


def main(argv: list[str]) -> int:
    if argv == ["--check"]:
        return check()
    if len(argv) != 1:
        sys.exit(__doc__)
    doc = verify_catalog.validate_snapshot(Path(argv[0]))
    body = render(doc)
    WEB.write_text(body, encoding="utf-8")
    NATIVE.write_text(body, encoding="utf-8")
    APP_JS.write_text(app_js_with(doc), encoding="utf-8")
    subprocess.run(["node", str(GUIDED)], check=True)
    print(f"imported {len(doc['targets'])} targets, snapshot {doc['snapshotDigest']}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
